insert into public.ppg_skill_domains
  (domain, label_th, label_en)
values
  ('Visual Objects', 'วัตถุและภาพ', 'Visual Objects'),
  ('Data Visualization', 'แผนภูมิและกราฟ', 'Data Visualization')
insert into public.ppg_modules
  (module_key, course_key, order_index, skill_domain, title_th, title_en, summary_th, summary_en, publication_state)
values
  ('chapter-05', 'presentation-program', 5, 'Visual Objects', 'การแทรกวัตถุลงในการนำเสนอ', 'Inserting objects into a presentation', 'แทรกภาพจากไฟล์ ออนไลน์และคลิปอาร์ต แก้ไขภาพ และแทรกรูปร่างพร้อมใช้', 'Inserting pictures from file, online and clip art, editing pictures, and inserting and editing ready-made shapes.', 'published'),
  ('chapter-06', 'presentation-program', 6, 'Data Visualization', 'แผนภูมิและกราฟ', 'Charts and graphs', 'การสร้างแผนภูมิ แท็บ Chart Design องค์ประกอบและการตกแต่งแผนภูมิ', 'Creating charts and graphs, the Chart Design tab and chart elements, and chart styling on the Format tab.', 'published')
insert into public.ppg_lessons
  (lesson_key, module_key, order_index, title_th, title_en, what_learn_th, what_learn_en, why_th, why_en, body_th, body_en, what_next_th, what_next_en, publication_state)
values
  ('chapter-05-lesson-01', 'chapter-05', 1, 'การแทรกภาพจากไฟล์ ออนไลน์และคลิปอาร์ต', 'Inserting pictures from file, online, and clip art', 'แทรกภาพจากไฟล์ จากแหล่งออนไลน์ และจากคลิปอาร์ต', 'Insert pictures from a file, from an online source, and from clip art.', 'ภาพที่เหมาะสมอธิบายได้เร็วกว่าข้อความยาว', 'A suitable picture explains faster than a long passage of text.', 'ภาพจากสามแหล่งหลักคือไฟล์ในคอมพิวเตอร์ ค้นหาออนไลน์ และคลิปอาร์ตที่มีในโปรแกรม แทรกภาพเริ่มจากแท็บ Insert จากนั้นเลือก Pictures และเลือกแหล่งเช่นไฟล์ ออนไลน์หรือคลิปอาร์ต ตรวจใบอนุญาตและความละเอียดของภาพก่อนใช้กับข้อเสนอลูกค้า', 'Pictures come from three main sources: a file on your computer, an online search, and clip art built into the program. To insert a picture, open the Insert tab, choose Pictures, then choose the source, such as file, online, or clip art. Check the licence and the resolution before you use a picture in a customer proposal.', 'ต่อไป: แก้ไขภาพ ตัด การแก้ไขและเอฟเฟกต์', 'Next: editing pictures with crop, corrections, and effects.', 'published'),
  ('chapter-05-lesson-02', 'chapter-05', 2, 'การแก้ไขภาพ:การใช้ตัด ความสว่าง เอฟเฟกต์และเค้าโครงภาพ', 'Editing pictures: crop, corrections, effects, and layout', 'ตัดภาพปรับความสว่างและความคมชัดเพิ่มเอฟเฟกต์และเลือกเค้าโครงภาพได้', 'Crop a picture, adjust brightness and contrast, add an effect, and choose a picture layout.', 'แก้ไขภาพดีทำให้เนื้อหาเด่นโดยไม่ต้องเปลี่ยนภาพไหม่', 'Good picture editing makes the content stand out without needing a new photo.', 'การใช้ตัดคือลดขอบของภาพที่ไม่ใช้ การแก้ไขปรับความสว่างและความคมชัด เอฟเฟกต์เปลี่ยนลักษณะเช่นดินสอ และเค้าโครงภาพใส่ภาพในกรอบกับข้อความ', 'Crop trims the edges you do not need. Corrections adjust brightness and contrast. Effects change the look, such as a pencil sketch. Picture Layout places the picture in a frame beside text.', 'ต่อไป: แทรกและแก้ไขรูปร่างพร้อมใช้', 'Next: inserting and editing ready-made shapes.', 'published'),
  ('chapter-05-lesson-03', 'chapter-05', 3, 'การแทรกและแก้ไขรูปร่างพร้อมใช้', 'Inserting and editing ready-made shapes', 'แทรกรูปร่างจากแกลเลอรี เปลี่ยนเติมสีรูปร่างและเส้นขอบรูปร่าง เพิ่มข้อความและจัดวางลำดับได้', 'Insert a shape from the gallery, change its fill and outline, add text, and arrange the order.', 'รูปร่างช่วยอธิบายความสัมพันธ์ระหว่างความคิดเช่นขั้นตอนและลำดับ', 'Shapes explain relationships between ideas, such as steps in a process.', 'รูปร่างพร้อมใช้จากแกลเลอรีเช่นลูกศรกล่องคำพูดและกล่องข้อความ หลังแทรกสามารถเปลี่ยนเติมสีรูปร่างเส้นขอบรูปร่างและเอฟเฟกต์ พิมพ์ข้อความในรูปร่างและจัดวางลำดับด้วย Bring Forward Send Backward หรือ Group', 'Ready-made shapes come from the Shapes gallery: arrows, callouts, and boxes with text. After inserting one, you can change the Shape Fill, Shape Outline, and effects, type text inside it, and arrange the order with Bring Forward, Send Backward, or Group.', 'ต่อไป: ภารกิจความรู้และข้อสอบหลังเรียน', 'Next: the Knowledge Mission and the chapter post-test.', 'published'),
  ('chapter-06-lesson-01', 'chapter-06', 1, 'การสร้างแผนภูมิและกราฟ', 'Creating charts and graphs', 'เลือกชนิดแผนภูมิที่เหมาะสมกับข้อมูลและสร้างแผนภูมิได้', 'Choose a chart type that fits the data and create a chart.', 'แผนภูมิช่วยให้เห็นรูปแบบของตัวเลขเร็ว', 'A chart helps the audience see the pattern in the numbers quickly.', 'แผนภูมิเปลี่ยนตารางของตัวเลขกลายเป็นภาพ ประเภทที่ใช้บ่อยคือแผนภูมิคอลัมน์ แผนภูมิเส้นและแผนภูมิวงกลม เลือกแผนภูมิคอลัมน์เพื่อเปรียบเทียบค่า แผนภูมิเส้นเพื่อแสดงแนวโน้มตามเวลา และแผนภูมิวงกลมเพื่อแสดงส่วนของทั้งหมด', 'A chart turns a table of numbers into a picture. The types used most are column, line, and pie. Choose a column chart to compare values, a line chart to show a trend over time, and a pie chart to show parts of a whole.', 'ต่อไป: แท็บ Chart Design และองค์ประกอบแผนภูมิ', 'Next: the Chart Design tab and chart elements.', 'published'),
  ('chapter-06-lesson-02', 'chapter-06', 2, 'แท็บ Chart Design และองค์ประกอบแผนภูมิ', 'The Chart Design tab and chart elements', 'ใช้แท็บ Chart Design เพื่อเปลี่ยนประเภทแผนภูมิ แก้ไขข้อมูลและเพิ่มองค์ประกอบแผนภูมิได้', 'Use the Chart Design tab to change the chart type, edit the data, and add chart elements.', 'องค์ประกอบที่เหมาะสมช่วยให้ผู้ฟังอ่านแผนภูมิได้คนเดียว', 'Suitable elements help the audience read the chart without extra explanation.', 'เลือกแผนภูมิจากนั้นแท็บ Chart Design จะแสดงขึ้น ใช้ Add Chart Element เพื่อเพิ่มชื่อเรื่อง ชื่อแกน คำอธิบาย ป้ายกำกับข้อมูลและเส้นตาราง ใช้ Change Chart Type เพื่อสลับระหว่างแผนภูมิคอลัมน์ แผนภูมิเส้นและแผนภูมิวงกลม และ Edit Data เพื่อเปลี่ยนตัวเลข', 'Select the chart and the Chart Design tab appears. Use Add Chart Element to turn on the chart title, axis titles, legend, data labels, and gridlines. Use Change Chart Type to switch between column, line, and pie, and Edit Data to change the numbers.', 'ต่อไป: แท็บ Format และการตกแต่งแผนภูมิ', 'Next: the Format tab and chart styling.', 'published'),
  ('chapter-06-lesson-03', 'chapter-06', 3, 'แท็บ Format และการตกแต่งแผนภูมิ', 'The Format tab and chart styling', 'ใช้แท็บ Format เพื่อเปลี่ยนเติมสี เส้นขอบและเอฟเฟกต์ และการตกแต่งแผนภูมิเพื่อจุดสำคัญเด่นได้', 'Use the Format tab to change fills, outlines, and effects, and style the chart so the key point stands out.', 'การตกแต่งมีประโยชน์เท่านั้นเมื่อทำให้จุดสำคัญเห็นง่ายขึน', 'Styling is useful only when it makes the key point easier to see.', 'แท็บ Format ตกแต่งองค์ประกอบแผนภูมิที่เลือก เติมสีรูปร่าง เส้นขอบรูปร่างและเอฟเฟกต์ ใช้ Chart Styles เพื่อให้มีลักษณะสม่ำเสมอเร็ว ใช้สีน้อยลงและเน้นหนึ่งชุดข้อมูลเพื่อให้ข้อความชัดเจน', 'The Format tab styles the selected chart element: Shape Fill, Shape Outline, and Shape Effects. Use Chart Styles for a quick consistent look. Use fewer colours and highlight one series to make the message clear.', 'ต่อไป: ภารกิจความรู้และข้อสอบหลังเรียน', 'Next: the Knowledge Mission and the chapter post-test.', 'published')
insert into public.ppg_lesson_steps
  (lesson_key, order_index, kind, body_th, body_en, check_prompt_th, check_prompt_en, check_answer_key, check_explanation_th, check_explanation_en)
values
  ('chapter-05-lesson-01', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะแทรกภาพจากไฟล์ แหล่งออนไลน์และคลิปอาร์ตได้', 'By the end you can insert pictures from a file, an online source, and clip art.', null, null, null, null, null),
  ('chapter-05-lesson-01', 2, 'explanation', 'ทุกภาพจะกลายเป็นวัตถุที่ย้าย ปรับขนาดและแก้ไขได้', 'Every picture becomes an object you can move, resize, and edit.', null, null, null, null, null),
  ('chapter-05-lesson-01', 3, 'example', 'ตัวอย่างทีมขายแทรกภาพสินค้าจากไฟล์แชร์ในข้อเสนอ', 'Example: the sales team inserts a product photo from a shared file into the proposal.', null, null, null, null, null),
  ('chapter-05-lesson-01', 4, 'explanation', 'ภาพออนไลน์มีลิขสิทธิ์จึงต้องตรวจใบอนุญาตก่อนใช้ เลือกภาพที่ชัดเจนพอดีสำหรับสไลด์และพิมพ์', 'Online pictures carry copyright, so check the licence before you use one. Choose an image that is sharp enough for the slide and for print.', null, null, null, null, null),
  ('chapter-05-lesson-01', 5, 'check', '', '', 'ก่อนใช้ภาพออนไลน์ในข้อเสนอลูกค้าควรตรวจอะไรแรก', 'Before using an online picture in a customer proposal, what should you check first?', 'a', 'ภาพออนไลน์มีลิขสิทธิ์ และความละเอียดต่ำจะทำให้สไลด์ไม่ชัดเจน จึงต้องตรวจทั้งสองก่อนใช้', 'Online pictures carry copyright, and a low-resolution image looks blurred on a slide, so check both before you use it.'),
  ('chapter-05-lesson-01', 6, 'summary', 'เลือกภาพจากแหล่งที่เหมาะสม ตรวจใบอนุญาต และแทรกเพื่ออธิบาย', 'Pick a picture from a suitable source, check the licence, and insert it to explain, not to decorate.', null, null, null, null, null),
  ('chapter-05-lesson-02', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะตัดปรับความสว่างเพิ่มเอฟเฟกต์และเลือกเค้าโครงภาพได้', 'By the end you can crop a picture, adjust brightness, add an effect, and choose a picture layout.', null, null, null, null, null),
  ('chapter-05-lesson-02', 2, 'explanation', 'ตัดช่วยผู้ฟังเห็นจุดหลัก การแก้ไขช่วยภาพที่มืดหรือสว่างมากเกินไปอ่านง่าย', 'Cropping helps the audience see the main point. Corrections make a photo that is too dark or too bright easier to read.', null, null, null, null, null),
  ('chapter-05-lesson-02', 3, 'example', 'ตัวอย่างสไลด์รายงานความก้าวหน้าตัดภาพสินค้าให้เหลือเท่านั้นเครื่องจักรและปรับความสว่างให้มองเห็นชัดเจน', 'Example: a progress-report slide crops the factory photo down to the machine and raises the brightness so it is clearly visible.', null, null, null, null, null),
  ('chapter-05-lesson-02', 4, 'explanation', 'ไปที่ภาพเลือกภาพจากนั้นใช้แท็บรูปแบบเลือกตัด การแก้ไข เอฟเฟกต์หรือเค้าโครงภาพ ตัดเท่านั้นซ่อนขอบ ไม่ลบภาพ', 'Select the picture, then use the Format tab for Crop, Corrections, Effects, or Picture Layout. Cropping only hides the edges; it does not delete the picture.', null, null, null, null, null),
  ('chapter-05-lesson-02', 5, 'check', '', '', 'เมื่อตัดภาพส่วนที่ไม่ใช้จะกลายเป็นอะไร', 'When you crop a picture, what happens to the part you remove?', 'a', 'ตัดเท่านั้นซ่อนขอบที่ไม่ใช้ ภาพยังครบ จึงตัดอีกครั้งกู้คืนได้', 'Cropping only hides the edges you do not need. The full picture is still there, so you can crop again to recover it.'),
  ('chapter-05-lesson-02', 6, 'summary', 'ตัดให้จุดชัดเจน ปรับความสว่างพอดี และใช้เอฟเฟกต์เท่านั้นเมื่อช่วยเนื้อหา', 'Crop to the point, set brightness that is comfortable, and use effects only when they help the content.', null, null, null, null, null),
  ('chapter-05-lesson-03', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะแทรกรูปร่างเปลี่ยนเติมสีรูปร่างและเส้นขอบรูปร่าง เพิ่มข้อความและจัดวางลำดับได้', 'By the end you can insert a shape, change its fill and outline, add text, and arrange the order.', null, null, null, null, null),
  ('chapter-05-lesson-03', 2, 'explanation', 'รูปร่างคือวัตถุที่ปรับขนาดหมุนพลิกและกลุ่มกับรูปร่างอื่นได้', 'A shape is an object you can resize, rotate, flip, and group with other shapes.', null, null, null, null, null),
  ('chapter-05-lesson-03', 3, 'example', 'ตัวอย่างสไลด์ขั้นตอนขออนุมัติใช้รูปร่างลูกศรสามรูปร่างเชื่อมลำดับเพื่อแสดงลำดับสำหรับงาน', 'Example: an approval-process slide uses three arrow shapes connected in sequence to show the workflow.', null, null, null, null, null),
  ('chapter-05-lesson-03', 4, 'explanation', 'ไปที่แท็บ Insert เลือก Shapes จากนั้นคลิกรูปร่างที่ต้องการ เปลี่ยนสีที่ Shape Fill และ Shape Outline คลิกขวาเลือก Add Text เพื่อพิมพ์ในรูปร่าง', 'Go to the Insert tab, choose Shapes, then click the shape you want. Change the colour at Shape Fill and Shape Outline, then right-click and choose Add Text to type inside the shape.', null, null, null, null, null),
  ('chapter-05-lesson-03', 5, 'check', '', '', 'รูปร่างหนึ่งถูกซ่อนหลังรูปร่างอื่น ควรใช้คำสั่งใดเพื่อนำไปข้างหน้า', 'One shape is hidden behind another. Which command brings it to the front?', 'b', 'นำไปข้างหน้าย้ายรูปร่างที่เลือกไปหน้า จึงมองเห็นอีกครั้ง', 'Bring Forward moves the selected shape in front of the others, so it is visible again.'),
  ('chapter-05-lesson-03', 6, 'summary', 'แทรกรูปร่างจากแกลเลอรี ตั้งเติมสีรูปร่างและเส้นขอบรูปร่าง และจัดวางลำดับกับ Bring Forward หรือ Send Backward', 'Insert a shape from the gallery, set its fill and outline, and arrange the order with Bring Forward or Send Backward.', null, null, null, null, null),
  ('chapter-06-lesson-01', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะเลือกชนิดแผนภูมิที่เหมาะสมกับข้อมูลและสร้างแผนภูมิได้', 'By the end you can choose a chart type that fits the data and create a chart.', null, null, null, null, null),
  ('chapter-06-lesson-01', 2, 'explanation', 'แผนภูมิเปลี่ยนตัวเลขกลายเป็นภาพที่ผู้ฟังอ่านได้เร็ว', 'A chart turns numbers into a picture the audience can read at a glance.', null, null, null, null, null),
  ('chapter-06-lesson-01', 3, 'example', 'ตัวอย่างรายงานขายเดือนใช้แผนภูมิเส้นเพื่อแสดงขายตามเวลาหกเดือน', 'Example: the monthly sales report uses a line chart to show sales over six months.', null, null, null, null, null),
  ('chapter-06-lesson-01', 4, 'explanation', 'ไปที่แท็บ Insert เลือก Chart เลือกชนิดจากนั้นแผ่นข้อมูลเปิดขึ้นสำหรับตัวเลขของคุณ', 'Go to the Insert tab, choose Chart, pick the chart type, then the data sheet opens for your numbers.', null, null, null, null, null),
  ('chapter-06-lesson-01', 5, 'check', '', '', 'แผนภูมิใดเหมาะสมสำหรับแสดงแนวโน้มตามเวลา', 'Which chart suits showing a trend over time?', 'b', 'แผนภูมิเส้นแสดงแนวโน้มตามเวลาชัดเจน แผนภูมิวงกลมแสดงส่วนของทั้งหมด และแผนภูมิคอลัมน์เปรียบเทียบค่าระหว่างหมวด', 'A line chart shows a trend over time clearly. A pie chart shows parts of a whole, and a column chart compares values between categories.'),
  ('chapter-06-lesson-01', 6, 'summary', 'เลือกแผนภูมิที่พอดีกับข้อมูลและจุดสำคัญ ไม่เลือกเพราะภาพสวยงาม', 'Choose the chart that fits the data and the key point, not because it looks pretty.', null, null, null, null, null),
  ('chapter-06-lesson-02', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะใช้แท็บ Chart Design เพื่อเปลี่ยนประเภทแผนภูมิ แก้ไขข้อมูลและเพิ่มองค์ประกอบแผนภูมิได้', 'By the end you can use the Chart Design tab to change the chart type, edit the data, and add chart elements.', null, null, null, null, null),
  ('chapter-06-lesson-02', 2, 'explanation', 'องค์ประกอบของแผนภูมิเพิ่มความหมายเช่นชื่อเรื่อง คำอธิบาย ชื่อแกน ป้ายกำกับข้อมูลและเส้นตาราง', 'Chart elements add meaning: the chart title, legend, axis titles, data labels, and gridlines.', null, null, null, null, null),
  ('chapter-06-lesson-02', 3, 'example', 'ตัวอย่างรายงานความก้าวหน้าเพิ่มป้ายกำกับข้อมูลเพื่อให้แตละแท่งแสดงค่า', 'Example: the progress report adds data labels so each bar shows its value.', null, null, null, null, null),
  ('chapter-06-lesson-02', 4, 'explanation', 'ใช้ Change Chart Type เพื่อสลับแผนภูมิ และ Edit Data เพื่อเปลี่ยนตัวเลข แผนภูมิอัปเดตทันที', 'Use Change Chart Type to switch the chart, and Edit Data to change the numbers; the chart updates at once.', null, null, null, null, null),
  ('chapter-06-lesson-02', 5, 'check', '', '', 'องค์ประกอบใดอธิบายที่สีแตละหมายถึงอะไร', 'Which element explains what each colour means?', 'a', 'คำอธิบายบอกผู้ฟังสีแตละหมายถึงอะไร ขณะที่ป้ายกำกับข้อมูลแสดงค่าและเส้นตารางช่วยอ่านค่า', 'The legend tells the audience what each colour means; data labels show values, and gridlines help read the scale.'),
  ('chapter-06-lesson-02', 6, 'summary', 'เลือกแผนภูมิ เพิ่มองค์ประกอบที่ผู้ฟังต้องรู้จัก และซ่อนองค์ประกอบที่ไม่ใช้', 'Select the chart, add the elements the audience needs, and leave out the rest.', null, null, null, null, null),
  ('chapter-06-lesson-03', 1, 'objective', 'เมื่อจบบทเรียนนี้คุณจะใช้แท็บ Format เพื่อเปลี่ยนเติมสีเส้นขอบและเอฟเฟกต์และทำให้จุดสำคัญเด่นได้', 'By the end you can use the Format tab to change fills, outlines, and effects, and make the key point stand out.', null, null, null, null, null),
  ('chapter-06-lesson-03', 2, 'explanation', 'รูปแบบตกแต่งองค์ประกอบหนึ่ง รูปแบบที่สม่ำเสมอทั้งหมดแผนภูมิอ่านง่ายกว่า', 'Format styles one element; one consistent style across the whole chart is easier to read.', null, null, null, null, null),
  ('chapter-06-lesson-03', 3, 'example', 'ตัวอย่างทีมให้ชุดข้อมูลหนึ่งคือน้ำเงินและชุดข้อมูลอื่นคือเทาเพื่อให้บรรทัดหลักเด่น', 'Example: the team makes one series blue and the others grey so the main line stands out.', null, null, null, null, null),
  ('chapter-06-lesson-03', 4, 'explanation', 'สีหลายมากเกินไปทำให้แผนภูมิรก ใช้สีน้อยลงและเก็บสีหนึ่งสำหรับชุดข้อมูลสำคัญ', 'Too many colours make a chart busy; use fewer colours and keep one colour for the key series.', null, null, null, null, null),
  ('chapter-06-lesson-03', 5, 'check', '', '', 'แผนภูมิรกเพราะสีหลายมากเกินไป ควรแก้ไขอย่างไร', 'The chart looks busy because there are too many colours. How should you fix it?', 'a', 'ใช้สีน้อยลงและเน้นชุดข้อมูลสำคัญ ไม่เพิ่มป้ายกำกับข้อมูลหรือทำให้แบบอักษรเล็ก', 'Use fewer colours and highlight the key series; adding more labels or shrinking the font does not fix a busy chart.'),
  ('chapter-06-lesson-03', 6, 'summary', 'ตกแต่งแผนภูมิเพื่อให้ข้อความชัดเจน ไม่เพื่อให้สีหลาย', 'Style the chart to make the message clear, not to add colour for its own sake.', null, null, null, null, null)
