insert into public.ppg_knowledge_missions
  (module_key, instructions_th, instructions_en)
values
  ('chapter-05', 'ภารกิจความรู้:ตอบคำถามหกข้อเกี่ยวกับภาพและรูปร่างผ่านที่ 70%และทำซ้ำได้ไม่จำกัด', 'Knowledge Mission: answer six questions about pictures and shapes. 70% passes; you can retry without limit.'),
  ('chapter-06', 'ภารกิจความรู้:ตอบคำถามหกข้อเกี่ยวกับแผนภูมิและกราฟผ่านที่ 70%และทำซ้ำได้ไม่จำกัด', 'Knowledge Mission: answer six questions about charts and graphs. 70% passes; you can retry without limit.')
insert into public.ppg_knowledge_mission_questions
  (module_key, order_index, option_key, prompt_th, prompt_en, option_th, option_en, is_correct, explanation_th, explanation_en, review_th, review_en)
values
  ('chapter-05', 1, 'a', 'ภาพแหล่งใดต้องใช้อินเทอร์เน็ต', 'Which picture source needs an internet connection?', 'ภาพออนไลน์', 'Online Pictures', true, 'ภาพออนไลน์ต้องใช้อินเทอร์เน็ตเพื่อค้นหา ขณะที่ภาพไฟล์ในคอมพิวเตอร์ไม่ต้อง', 'Online Pictures needs the internet to search; a file on your computer does not.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-05', 1, 'b', 'ภาพแหล่งใดต้องใช้อินเทอร์เน็ต', 'Which picture source needs an internet connection?', 'ภาพไฟล์', 'A picture file on your computer', false, 'ภาพออนไลน์ต้องใช้อินเทอร์เน็ตเพื่อค้นหา ขณะที่ภาพไฟล์ในคอมพิวเตอร์ไม่ต้อง', 'Online Pictures needs the internet to search; a file on your computer does not.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-05', 1, 'c', 'ภาพแหล่งใดต้องใช้อินเทอร์เน็ต', 'Which picture source needs an internet connection?', 'รูปร่างจากแกลเลอรี', 'A shape from the Shapes gallery', false, 'ภาพออนไลน์ต้องใช้อินเทอร์เน็ตเพื่อค้นหา ขณะที่ภาพไฟล์ในคอมพิวเตอร์ไม่ต้อง', 'Online Pictures needs the internet to search; a file on your computer does not.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-05', 2, 'a', 'ก่อนใช้ภาพออนไลน์ควรตรวจอะไร', 'What should you check before using an online picture?', 'ใบอนุญาตและลิขสิทธิ์', 'The licence and copyright', true, 'ภาพออนไลน์มีลิขสิทธิ์จึงต้องตรวจใบอนุญาตก่อนใช้ในงาน', 'An online picture carries copyright, so check its licence before using it at work.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-05', 2, 'b', 'ก่อนใช้ภาพออนไลน์ควรตรวจอะไร', 'What should you check before using an online picture?', 'ขนาดแบบอักษร', 'The font size', false, 'ภาพออนไลน์มีลิขสิทธิ์จึงต้องตรวจใบอนุญาตก่อนใช้ในงาน', 'An online picture carries copyright, so check its licence before using it at work.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-05', 2, 'c', 'ก่อนใช้ภาพออนไลน์ควรตรวจอะไร', 'What should you check before using an online picture?', 'ตัวเลขสไลด์', 'The slide number', false, 'ภาพออนไลน์มีลิขสิทธิ์จึงต้องตรวจใบอนุญาตก่อนใช้ในงาน', 'An online picture carries copyright, so check its licence before using it at work.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-05', 3, 'a', 'คำสั่งใดลดขอบของภาพโดยไม่ลบภาพ', 'Which command trims unwanted edges without deleting the picture?', 'ลบ', 'Delete', false, 'ตัดเท่านั้นซ่อนขอบที่ไม่ใช้ ไม่ลบภาพจากสไลด์', 'Crop only hides the edges you do not need; it does not delete the picture from the slide.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-05', 3, 'b', 'คำสั่งใดลดขอบของภาพโดยไม่ลบภาพ', 'Which command trims unwanted edges without deleting the picture?', 'ตัด', 'Crop', true, 'ตัดเท่านั้นซ่อนขอบที่ไม่ใช้ ไม่ลบภาพจากสไลด์', 'Crop only hides the edges you do not need; it does not delete the picture from the slide.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-05', 3, 'c', 'คำสั่งใดลดขอบของภาพโดยไม่ลบภาพ', 'Which command trims unwanted edges without deleting the picture?', 'ซ่อนสไลด์', 'Hide Slide', false, 'ตัดเท่านั้นซ่อนขอบที่ไม่ใช้ ไม่ลบภาพจากสไลด์', 'Crop only hides the edges you do not need; it does not delete the picture from the slide.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-05', 4, 'a', 'เครื่องมือใดปรับความสว่างและความคมชัด', 'Which tool adjusts brightness and contrast?', 'การแก้ไข', 'Corrections', true, 'การแก้ไขปรับความสว่างและความคมชัดเพื่อภาพมืดหรือสว่างอ่านง่าย', 'Corrections adjusts brightness and contrast so a dark or bright picture reads better.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-05', 4, 'b', 'เครื่องมือใดปรับความสว่างและความคมชัด', 'Which tool adjusts brightness and contrast?', 'ตัวหนา', 'Bold', false, 'การแก้ไขปรับความสว่างและความคมชัดเพื่อภาพมืดหรือสว่างอ่านง่าย', 'Corrections adjusts brightness and contrast so a dark or bright picture reads better.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-05', 4, 'c', 'เครื่องมือใดปรับความสว่างและความคมชัด', 'Which tool adjusts brightness and contrast?', 'ตัด', 'Crop', false, 'การแก้ไขปรับความสว่างและความคมชัดเพื่อภาพมืดหรือสว่างอ่านง่าย', 'Corrections adjusts brightness and contrast so a dark or bright picture reads better.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-05', 5, 'a', 'เอฟเฟกต์ใดคือศิลปะ', 'Which is an artistic effect?', 'การจัดลำดับเลข', 'Numbering', false, 'เอฟเฟกต์เปลี่ยนลักษณะเช่นดินสอสเก็ตช์ ขณะที่การจัดลำดับเลขและ Hide Slide ไม่ใช่เอฟเฟกต์', 'Effects change the look, such as a pencil sketch; numbering and hiding slides are not effects.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-05', 5, 'b', 'เอฟเฟกต์ใดคือศิลปะ', 'Which is an artistic effect?', 'ดินสอสเก็ตช์', 'Pencil sketch', true, 'เอฟเฟกต์เปลี่ยนลักษณะเช่นดินสอสเก็ตช์ ขณะที่การจัดลำดับเลขและ Hide Slide ไม่ใช่เอฟเฟกต์', 'Effects change the look, such as a pencil sketch; numbering and hiding slides are not effects.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-05', 5, 'c', 'เอฟเฟกต์ใดคือศิลปะ', 'Which is an artistic effect?', 'Hide Slide', 'Hide Slide', false, 'เอฟเฟกต์เปลี่ยนลักษณะเช่นดินสอสเก็ตช์ ขณะที่การจัดลำดับเลขและ Hide Slide ไม่ใช่เอฟเฟกต์', 'Effects change the look, such as a pencil sketch; numbering and hiding slides are not effects.', 'ทบทวนบทเรียนที่ 2', 'Review lesson 2'),
  ('chapter-05', 6, 'a', 'รูปร่างถูกซ่อนหลังรูปร่างอื่นควรใช้คำสั่งใด', 'A shape is hidden behind another. Which command should you use?', 'ตัด', 'Crop', false, 'นำไปข้างหน้าย้ายรูปร่างที่เลือกไปหน้าจึงมองเห็นอีกครั้ง', 'Bring Forward moves the selected shape in front, so it becomes visible again.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-05', 6, 'b', 'รูปร่างถูกซ่อนหลังรูปร่างอื่นควรใช้คำสั่งใด', 'A shape is hidden behind another. Which command should you use?', 'นำไปข้างหน้า', 'Bring Forward', true, 'นำไปข้างหน้าย้ายรูปร่างที่เลือกไปหน้าจึงมองเห็นอีกครั้ง', 'Bring Forward moves the selected shape in front, so it becomes visible again.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-05', 6, 'c', 'รูปร่างถูกซ่อนหลังรูปร่างอื่นควรใช้คำสั่งใด', 'A shape is hidden behind another. Which command should you use?', 'การแก้ไข', 'Corrections', false, 'นำไปข้างหน้าย้ายรูปร่างที่เลือกไปหน้าจึงมองเห็นอีกครั้ง', 'Bring Forward moves the selected shape in front, so it becomes visible again.', 'ทบทวนบทเรียนที่ 3', 'Review lesson 3'),
  ('chapter-06', 1, 'a', 'แผนภูมิมีประโยชน์อย่างไร', 'What is a chart good for?', 'แสดงตัวเลขและแนวโน้มเพื่อให้ผู้ฟังเห็นรูปแบบเร็ว', 'Showing numbers and trends so the audience sees the pattern quickly', true, 'แผนภูมิเปลี่ยนตัวเลขกลายเป็นภาพที่ผู้ฟังเห็นรูปแบบและแนวโน้มเร็ว', 'A chart turns numbers into a picture, so the audience sees patterns and trends quickly.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-06', 1, 'b', 'แผนภูมิมีประโยชน์อย่างไร', 'What is a chart good for?', 'ให้ข้อความยาวมากกว่า', 'Giving long passages of text', false, 'แผนภูมิเปลี่ยนตัวเลขกลายเป็นภาพที่ผู้ฟังเห็นรูปแบบและแนวโน้มเร็ว', 'A chart turns numbers into a picture, so the audience sees patterns and trends quickly.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-06', 1, 'c', 'แผนภูมิมีประโยชน์อย่างไร', 'What is a chart good for?', 'รายการชื่อของแหล่งข้อมูล', 'Listing the sources of the data', false, 'แผนภูมิเปลี่ยนตัวเลขกลายเป็นภาพที่ผู้ฟังเห็นรูปแบบและแนวโน้มเร็ว', 'A chart turns numbers into a picture, so the audience sees patterns and trends quickly.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-06', 2, 'a', 'แผนภูมิใดเหมาะสมสำหรับเปรียบเทียบค่าของหมวด', 'Which chart suits comparing values across categories?', 'แผนภูมิคอลัมน์', 'A column chart', true, 'แผนภูมิคอลัมน์เปรียบเทียบค่าระหว่างหมวดชัดเจน แผนภูมิวงกลมแสดงส่วนของทั้งหมด แผนภูมิเส้นแสดงแนวโน้ม', 'A column chart compares values between categories; pie shows parts of a whole and line shows a trend.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-06', 2, 'b', 'แผนภูมิใดเหมาะสมสำหรับเปรียบเทียบค่าของหมวด', 'Which chart suits comparing values across categories?', 'แผนภูมิวงกลม', 'A pie chart', false, 'แผนภูมิคอลัมน์เปรียบเทียบค่าระหว่างหมวดชัดเจน แผนภูมิวงกลมแสดงส่วนของทั้งหมด แผนภูมิเส้นแสดงแนวโน้ม', 'A column chart compares values between categories; pie shows parts of a whole and line shows a trend.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-06', 2, 'c', 'แผนภูมิใดเหมาะสมสำหรับเปรียบเทียบค่าของหมวด', 'Which chart suits comparing values across categories?', 'แผนภูมิเส้น', 'A line chart', false, 'แผนภูมิคอลัมน์เปรียบเทียบค่าระหว่างหมวดชัดเจน แผนภูมิวงกลมแสดงส่วนของทั้งหมด แผนภูมิเส้นแสดงแนวโน้ม', 'A column chart compares values between categories; pie shows parts of a whole and line shows a trend.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-06', 3, 'a', 'สร้างแผนภูมิเริ่มจากที่ไหน', 'Where do you start when creating a chart?', 'แท็บ Insert จากนั้น Chart', 'Insert tab, then Chart', true, 'สร้างแผนภูมิเริ่มจากแท็บ Insert เลือก Chart จากนั้นเลือกชนิด', 'Start at Insert, choose Chart, then choose the chart type.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
  ('chapter-06', 3, 'b', 'สร้างแผนภูมิเริ่มจากที่ไหน', 'Where do you start when creating a chart?', 'แท็บ Home จากนั้นตัวหนา', 'Home tab, then Bold', false, 'สร้างแผนภูมิเริ่มจากแท็บ Insert เลือก Chart จากนั้นเลือกชนิด', 'Start at Insert, choose Chart, then choose the chart type.', 'ทบทวนบทเรียนที่ 1', 'Review lesson 1'),
